def _check_uninferable_call (self,node):
    if not isinstance (node.func,astroid.Attribute):
        return # Look for properties. First, obtain 
        # the lhs of the Attribute node and search the attribute 
        # there. If that attribute is a property or a subclass of properties, 
        # then most likely it's not callable. 
        # TODO: since astroid doesn't understand descriptors very well 
        # we will not handle them here, right now. 
    expr = node.func.expr 
    klass = safe_infer (expr)
    if (klass is None or klass is astroid.Uninferable or not isinstance (klass,astroid.Instance)):
        return 
    try:
        attrs = klass._proxied.getattr (node.func.attrname)
    except exceptions.NotFoundError:
        return 
    for attr in attrs:
        if attr is astroid.Uninferable:
            continue 
        if not isinstance (attr,astroid.FunctionDef):
            continue 
        # Decorated, see if it is decorated with a property. 
        # Also, check the returns and see if they are callable. 
        if decorated_with_property (attr):
            try:
                all_returns_are_callable = all (return_node.callable ()or return_node is astroid.Uninferable for return_node in attr.infer_call_result (node))
            except astroid.InferenceError:
                continue 
            if not all_returns_are_callable:
