        if kwargs['msg'] == 'error':
            kwargs.update(error)
        else:
            kwargs['error'] = error
        if not isinstance(err,MeteorError):
            # not a client error, should always be logged.
            stack,_ = safe_call(self.logger.error,'%r %r',msg,data,exc_info=1,)
            if stack is not None:
                # something went wrong while logging the error, revert to
                # writing a stack trace to stderr.
                traceback.print_exc(file=sys.stderr)
                sys.stderr.write('Additionally, while handling the above error the following error was encountered:\n')
